#!/usr/bin/env python3
from itertools import product

def read_file(filename):
    with open(filename, 'rb') as f:
        return f.read().strip()

def split_pairs(data):
    pairs = []
    for i in range(0, len(data)-1, 2):
        pairs.append((data[i], data[i+1]))
    return pairs

def cnot(a, b):
    # CNOT: if first bit is 1, flip second bit
    return (a, a ^ b)

def reverse_cnot(a, b):
    # Reverse CNOT: if second bit is 1, flip first bit
    return (a ^ b, b)

def hadamard_like(a, b):
    # Try some Hadamard-like transformations
    return [
        (a ^ 0xFF, b),  # Flip all bits in first
        (a, b ^ 0xFF),  # Flip all bits in second
        (b, a),         # Swap positions
        (a ^ b, b),     # XOR first with second
        (a, a ^ b),     # XOR second with first
    ]

def try_transformations(data):
    results = []
    pairs = split_pairs(data)

    # Try CNOT and reverse CNOT
    cnot_result = bytes([x for pair in [cnot(a,b) for a,b in pairs] for x in pair])
    rev_cnot_result = bytes([x for pair in [reverse_cnot(a,b) for a,b in pairs] for x in pair])

    results.append(("CNOT", cnot_result))
    results.append(("Reverse CNOT", rev_cnot_result))

    # Try Hadamard-like transformations
    for i, pair in enumerate(pairs):
        for h_transform in hadamard_like(*pair):
            new_pairs = pairs.copy()
            new_pairs[i] = h_transform
            result = bytes([x for pair in new_pairs for x in pair])
            results.append((f"Hadamard-like at pos {i}", result))

    return results

def is_printable(byte):
    return 32 <= byte <= 126

def looks_like_flag(data):
    # Check if the result contains common flag characters
    try:
        text = data.decode('ascii')
        return 'flag{' in text or 'FLAG{' in text
    except:
        return False

def analyze_output():
    data = read_file('/home/ctfplayer/ctf_files/output')
    print(f"Original data: {data}")

    # Look for flag format pattern
    print("\nAnalyzing possible transformations...")
    results = try_transformations(data)

    for desc, result in results:
        if any(is_printable(b) for b in result):
            try:
                text = result.decode('ascii', errors='replace')
                print(f"\n{desc}:")
                print(f"ASCII: {text}")
                if looks_like_flag(result):
                    print("*** Possible flag found! ***")
            except:
                continue

    # Special focus on $ characters
    print("\nAnalyzing $ character relationships:")
    pairs = split_pairs(data)
    for i, (a, b) in enumerate(pairs):
        if a == ord('$') or b == ord('$'):
            print(f"$ found at pair {i}: {chr(a)}{chr(b)}")
            # Try special transformations around $ characters
            for transform in hadamard_like(a, b):
                result = bytes([transform[0]]) + bytes([transform[1]])
                try:
                    print(f"Transform result: {result.decode('ascii')}")
                except:
                    continue

if __name__ == '__main__':
    analyze_output()

