def sliding_window_decode(data):
    results = []
    # Try sliding window of 3 characters
    for i in range(len(data)-2):
        window = data[i:i+3]
        # If middle character is $, use it as control qubit
        if window[1] == ord('$'):
            # Try CNOT-like operations
            result1 = bytes([window[0] ^ window[2], window[1], window[2]])
            result2 = bytes([window[0], window[1], window[0] ^ window[2]])
            results.append(result1)
            results.append(result2)
    return results

def try_decode_with_key(data, key):
    result = bytearray()
    for i, b in enumerate(data):
        result.append(b ^ key[i % len(key)])
    return bytes(result)

