    # Use $ positions as a key
    key = bytes(dollar_positions)
    decoded = try_decode_with_key(data, key)
    print(f"\nUsing $ positions as key: {decoded}")

    # Try quantum-inspired sliding window decode
    print("\nSliding window results:")
    windows = sliding_window_decode(data)
    for i, window in enumerate(windows):
        try:
            print(f"Window {i}: {window.decode('ascii')}")
