#!/usr/bin/env python3

def read_file(filename):
    with open(filename, 'rb') as f:
        return f.read().strip()

def quantum_transform(data):
    # Split into chunks of two qubits
    chunks = [data[i:i+2] for i in range(0, len(data), 2)]
    results = []

    # Try different transformations based on quantum operations
    for i in range(len(chunks)):
        transformed = bytearray(data)
        # Apply CNOT-like operation with control qubit
        if i < len(chunks)-1:
            # Forward CNOT
            transformed[i*2+2] ^= transformed[i*2]
        if i > 0:
            # Reverse CNOT
            transformed[i*2-2] ^= transformed[i*2]
        results.append(transformed)

        # Special handling for $ characters
        if chunks[i][0] == ord('$') or (len(chunks[i]) > 1 and chunks[i][1] == ord('$')):
            # Apply controlled-NOT operation
            if i < len(chunks)-1:
                transformed2 = bytearray(transformed)
                transformed2[i*2+2:i*2+4] = bytes([b ^ ord('f') for b in transformed2[i*2+2:i*2+4]])
                results.append(transformed2)

    return results

def main():
    data = read_file('/home/ctfplayer/ctf_files/output')
    print(f"Original data: {data.decode('ascii')}")

    # Apply quantum transformations
    print("\nApplying quantum transformations:")
    results = quantum_transform(data)

    for i, result in enumerate(results):
        try:
            decoded = result.decode('ascii')
            if any(c in decoded for c in 'flag{'):
                print(f"\nPotential flag pattern found in transform {i}:")
                print(decoded)
            if '$' in decoded:
                # Look for patterns around $ characters
                print(f"\nTransform {i} with $ pattern:")
                print(decoded)
        except:
            continue

    # Apply final transformation focusing on $ as control qubits
    final = bytearray(data)
    for i in range(len(final)):
        if i > 0 and chr(final[i-1]) == '$':
            # Use $ as control qubit to transform next character
            if i+1 < len(final):
                final[i+1] ^= final[i]
            final[i] ^= ord('f') # Try with flag pattern

    try:
        print("\nFinal transformation:")
        print(final.decode('ascii', errors='replace'))
    except:
        pass

if __name__ == '__main__':
    main()

