from itertools import product

def cnot_control_first(a, b):
    # CNOT gate with first qubit as control
    return (a, a ^ b)

def cnot_control_second(a, b):
    # CNOT gate with second qubit as control
    return (a ^ b, b)

def swap_qubits(a, b):
    # SWAP operation
    return (b, a)

def hadamard_both(a, b):
    # Simulate Hadamard on both qubits (simplified)
    # Note: This is a simplified version since real Hadamard would involve superposition
    return (~a & 0xFF, ~b & 0xFF)

def try_transformations(pair):
    results = []
    char1, char2 = pair

    # Convert chars to numbers
    n1, n2 = ord(char1), ord(char2)

    # Try each transformation
    transforms = [
        ("CNOT1", cnot_control_first(n1, n2)),
        ("CNOT2", cnot_control_second(n1, n2)),
        ("SWAP", swap_qubits(n1, n2)),
        ("HAD", hadamard_both(n1, n2))
    ]

    for name, (r1, r2) in transforms:
        try:
            result = chr(r1) + chr(r2)
            results.append((name, result))
        except:
            pass

    return results

def main():
    output = "wxqvn$Zae${deyZv$d\"i"
    target = "flag{"

    # Process pairs of characters
    pairs = [(output[i], output[i+1]) for i in range(0, len(output)-1, 2)]

    print("Analyzing character pairs:")
    for i, pair in enumerate(pairs):
        print(f"\nPair {i}: {pair}")
        results = try_transformations(pair)

        for transform, result in results:
            if any(t in result for t in target):
                print(f"  {transform}: {result} (Potential match - contains part of {target})")
            else:
                print(f"  {transform}: {result}")

    # Try sequences of transformations on pairs
    print("\nTrying transformation sequences on first few pairs...")
    sequences = list(product(["CNOT1", "CNOT2", "SWAP", "HAD"], repeat=2))

    first_pairs = pairs[:3]  # Focus on first few pairs where 'flag{' should be
    for pair in first_pairs:
        for seq in sequences:
            current = pair
            for transform in seq:
                n1, n2 = ord(current[0]), ord(current[1])
                if transform == "CNOT1":
                    r1, r2 = cnot_control_first(n1, n2)
                elif transform == "CNOT2":
                    r1, r2 = cnot_control_second(n1, n2)
                elif transform == "SWAP":
                    r1, r2 = swap_qubits(n1, n2)
                else:  # HAD
                    r1, r2 = hadamard_both(n1, n2)
                try:
                    current = (chr(r1), chr(r2))
                except:
                    continue

            try:
                result = ''.join(current)
                if any(t in result for t in target):
                    print(f"Sequence {seq} on {pair}: {result} (Potential match)")
            except:
                continue

if __name__ == "__main__":
