def apply_transform_to_string(input_str, transform_seq):
    result = ""
    for i in range(0, len(input_str)-1, 2):
        a, b = ord(input_str[i]), ord(input_str[i+1])
        for transform in transform_seq:
            if transform == "CNOT1":
                a, b = (a, a ^ b)
            elif transform == "CNOT2":
                a, b = (a ^ b, b)
            elif transform == "SWAP":
                a, b = b, a
        try:
            result += chr(a) + chr(b)
        except:
            return None
    return result

