#!/usr/bin/env python3

def quantum_controlled_not(text):
    # Split into quantum registers
    registers = text.split('$')

    # Process each register
    result = []
    for reg in registers:
        if 'Z' in reg:
            # Z acts as control qubit
            parts = reg.split('Z')
            # Apply CNOT-like operation
            transformed = ''
            for c in parts[-1]:
                if c.isalpha():
                    # Flip through the alphabet
                    base = ord('a' if c.islower() else 'A')
                    transformed += chr((ord(c) - base + 13) % 26 + base)
                else:
                    transformed += c
            result.append(parts[0] + transformed)
        else:
            result.append(reg)

    processed = ''.join(result)

    # Convert " to } for flag format
    processed = processed.replace('"', '}')

    # Ensure proper flag format
    if not processed.startswith('flag{'):
        processed = 'flag{' + processed + '}'

    return processed

# Original quantum output
quantum_output = "wxqvn$Zae${deyZv$d\"i"

# Apply quantum transformation
result = quantum_controlled_not(quantum_output)
print("Transformed result:", result)

# Try additional transformations
def caesar_shift(text, shift):
    result = ''
    for c in text:
        if c.isalpha():
            is_upper = c.isupper()
            c = c.lower()
            shifted = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
            result += shifted.upper() if is_upper else shifted
        else:
            result += c
    return result

# Try different Caesar shifts on the result
for i in range(1, 14):
    shifted = caesar_shift(result, i)
    print(f"ROT{i}:", shifted)

# Try reverse engineering based on known flag format
def reverse_quantum(ciphertext):
    sections = ciphertext.split('$')
    transformed = []
    for section in sections:
        if section.startswith('Z'):
            # Reverse the quantum gate effect
            transformed.append(''.join(caesar_shift(c, -13) if c.isalpha() else c for c in section[1:]))
        else:
            transformed.append(section)
    return ''.join(transformed)

reversed_text = reverse_quantum(quantum_output)
print("\nReversed quantum transformation:", reversed_text)

# Try binary transformation (quantum states are binary)
def binary_transform(text):
    result = ''
    for i, c in enumerate(text):
        if c.isalpha():
            # Toggle based on position
            if i % 2 == 0:
                result += chr((ord(c) - ord('a') + 13) % 26 + ord('a'))
            else:
                result += c
        else:
            result += c
    return result

binary_result = binary_transform(quantum_output)
print("Binary transformation:", binary_result)

